{
  "case_id": "xsu_sg_007_work_stopped_due_to_impairment",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret har den rigtige hovedkonklusion: arbejdsophør giver ikke i sig selv ret. Det tilføjer dog en væsentlig forkert eller ustøttet vurdering: at Udbetaling Danmark tager stilling til aktiverings- og jobsøgningskrav for kontanthjælp eller førtidspension. Det står ikke i kilderne. Samtidig udelader det den centrale vurdering af arbejdets karakter og andre typer arbejde."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Ingen af de tre kritiske elementer er med: (1) at arbejdets karakter sammenholdes med funktionsnedsættelsen, (2) at sagens øvrige oplysninger bruges til at vurdere andre typer arbejde, (3) at skånehensyn eller mindre omfang indgår. Svaret nævner kun generelt evnen til at opnå og beholde arbejde."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Svaret besvarer, at arbejdsophør ikke i sig selv giver ret. Det besvarer ikke, hvad Udbetaling Danmark vurderer i den situation. Det erstatter den konkrete vurdering med generelle formuleringer og et irrelevant afsnit om aktivering og jobsøgning."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtten for påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer, at Udbetaling Danmark vil vurdere, om ansøgeren kan efterkomme aktiverings- og jobsøgningskrav ved kontanthjælp eller førtidspension. Det har ingen støtte i materialet. Det tilføjer også, at begrænsningen skal være så stor, at den 'i sig selv berettiger', hvilket er en uklar og ustøttet formulering."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer, at arbejdsophør ikke i sig selv afgør retten. Det bevarer ikke, at ophøret er udgangspunkt for en nærmere vurdering af arbejdets karakter og andre jobmuligheder. Eksemplet med ikke-fysisk belastende arbejde er ikke med, men det er kun et eksempel."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svarets trin er indbyrdes sammenhængende. Konklusionen om, at arbejdsophør ikke er nok og at der kræves en varig og særlig stor begrænsning, følger af de oplyste kriterier. Svaret rummer ingen intern modsigelse."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret fremstiller aktiverings- og jobsøgningsvurderingen som noget, Udbetaling Danmark 'vil' foretage, uden støtte i kilderne. Det gengiver heller ikke, at bekendtgørelsen siger, at Udbetaling Danmark 'kan' bestemme, og at vurderingen sker ud fra arten og graden af funktionsnedsættelsen."
    }
  },
  "xhaile_coverage": {
    "A22": {
      "label": "partial",
      "reason": "Svaret behandler arbejdsophør på grund af funktionsnedsættelse og siger, at det ikke i sig selv giver ret. Det nævner ikke, at der ses på arbejdets karakter i forhold til funktionsnedsættelsen, eller at der vurderes skånebehov og gener."
    },
    "A23": {
      "label": "no",
      "reason": "Svaret nævner ikke vurderingen af, om ansøgeren kan varetage andre typer arbejde, eventuelt med skånehensyn eller i mindre omfang."
    }
  },
  "overall_notes": "Svaret har den rigtige negative hovedkonklusion, men mangler kernen i vurderingen: arbejdets karakter, andre typer arbejde, skånehensyn og mindre omfang. Det indfører desuden en ustøttet vurdering af aktiverings- og jobsøgningskrav og angiver ingen kilder."
}

